public class ArrayUtils {
    public static int nullSafeHashCode(long[] array) {
        if (array == null) {
            return 0;
        }
        int hashCode = 1;
        for (long element : array) {
            hashCode = 31 * hashCode + (int) (element ^ (element >>> 32));
        }
        return hashCode;
    }

    public static void main(String[] args) {
        long[] array1 = {1L, 2L, 3L};
        long[] array2 = null;
        System.out.println(nullSafeHashCode(array1)); // Output: 10090603
        System.out.println(nullSafeHashCode(array2)); // Output: 0
    }
}

import java.util.NoSuchElementException;

public class BinaryTree<T> {
    private static class TreeNode<T> {
        T value;
        TreeNode<T> left;
        TreeNode<T> right;

        TreeNode(T value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    private TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            throw new NoSuchElementException("Node must have a left child to perform a right rotation.");
        }

        TreeNode<T> newParent = node.left;
        node.left = newParent.right;
        newParent.right = node;

        return newParent;
    }

    public static void main(String[] args) {
        // Example usage
        TreeNode<Integer> root = new TreeNode<>(10);
        root.left = new TreeNode<>(5);
        root.right = new TreeNode<>(15);

        TreeNode<Integer> newRoot = rotateRight(root);
        System.out.println("New root value: " + newRoot.value); // Output: 5
        System.out.println("New root's left child value: " + newRoot.left.value); // Output: 10
        System.out.println("New root's right child value: " + newRoot.right.value); // Output: 15
    }
}

