public class ClassPathManager {

    @SuppressWarnings("unchecked")
    public static void addToClassPath(Vector<URL> cpV, String dir) {
        File dirFile = new File(dir);
        if (dirFile.exists() && dirFile.isDirectory()) {
            File[] jarFiles = dirFile.listFiles((file) -> file.getName().endsWith(".jar"));
            if (jarFiles != null) {
                for (File jarFile : jarFiles) {
                    try {
                        URL jarUrl = jarFile.toURI().toURL();
                        cpV.add(jarUrl);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        } else {
            System.out.println("Directory does not exist or is not a directory.");
        }
    }

    public static void main(String[] args) {
        Vector<URL> classPath = new Vector<>();
        addToClassPath(classPath, "/path/to/your/jars");
        // Now you can use the classPath vector to set the classpath for your application
    }
}

