public class GraphGenerator {

    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (target == null || resultMap == null) {
            throw new IllegalArgumentException("Graph and resultMap cannot be null");
        }

        // Create two sets for the two partitions
        Set<V> partition1 = new HashSet<>();
        Set<V> partition2 = new HashSet<>();

        // Add vertices to the partitions based on the resultMap
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            if (entry.getKey().contains("partition1")) {
                partition1.add(entry.getValue());
            } else if (entry.getKey().contains("partition2")) {
                partition2.add(entry.getValue());
            } else {
                throw new IllegalArgumentException("Invalid partition key in resultMap");
            }
        }

        // Add edges between vertices in different partitions
        for (V v1 : partition1) {
            for (V v2 : partition2) {
                target.addEdge(v1, v2);
            }
        }
    }
}

public class BufferSearcher {

    /**
     * Searches for a byte of specified value in the <code>buffer</code>, starting at the specified <code>position</code>.
     * @param value The value to find.
     * @param pos   The starting position for searching.
     * @return The position of byte found, counting from beginning of the<code>buffer</code>, or <code>-1</code> if not found.
     */
    protected int findByte(byte value, int pos) {
        for (int i = pos; i < buffer.length; i++) {
            if (buffer[i] == value) {
                return i;
            }
        }
        return -1;
    }

