public class Bucket {
    // Assuming Bucket class has a constructor and other necessary methods

    public void insertBefore(Bucket bucket) {
        if (bucket == null) {
            throw new IllegalArgumentException("Bucket cannot be null");
        }

        if (this.previous == null) {
            // If this bucket is the head, set the new bucket as the head
            bucket.next = this;
            this.previous = bucket;
        } else {
            // Otherwise, insert the new bucket before this bucket
            bucket.next = this;
            bucket.previous = this.previous;
            this.previous.next = bucket;
            this.previous = bucket;
        }
    }
}

