import java.util.ArrayList;
import java.util.List;

public class TimeRangeBuilder {

    private static final long FETCH_DATA_DURATION = 1000 * 60 * 60 * 24; // 1 day in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start + FETCH_DATA_DURATION;

        while (currentStart < end) {
            if (currentEnd > end) {
                currentEnd = end;
            }
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart += FETCH_DATA_DURATION;
            currentEnd += FETCH_DATA_DURATION;
        }

        return timeRanges;
    }

    public static void main(String[] args) {
        TimeRangeBuilder builder = new TimeRangeBuilder();
        long start = System.currentTimeMillis() - 1000 * 60 * 60 * 24; // 1 day ago
        long end = System.currentTimeMillis() + 1000 * 60 * 60 * 24; // 1 day from now
        List<TimeRange> timeRanges = builder.buildTimeRanges(start, end);
        for (TimeRange range : timeRanges) {
            System.out.println("Start: " + range.getStart() + ", End: " + range.getEnd());
        }
    }
}

