public class ByteArrayConverter {

    /**
     * Converts an array of object Bytes to primitives.
     * <p>This method returns <code>null</code> for a <code>null</code> input array.</p>
     * @param array  a <code>Byte</code> array, may be <code>null</code>
     * @return a <code>byte</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static byte[] toPrimitive(final Byte[] array) {
        if (array == null) {
            return null;
        }
        byte[] primitiveArray = new byte[array.length];
        for (int i = 0; i < array.length; i++) {
            if (array[i] == null) {
                throw new NullPointerException("Array content cannot be null");
            }
            primitiveArray[i] = array[i].byteValue();
        }
        return primitiveArray;
    }

    public static void main(String[] args) {
        Byte[] byteArray = {1, 2, 3, 4, 5};
        byte[] primitiveArray = toPrimitive(byteArray);
        for (byte b : primitiveArray) {
            System.out.print(b + " ");
        }
    }
}

public class TimeBucketCompressor {

    /**
     * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
     */
    public static long compressTimeBucket(long timeBucket, int dayStep) {
        int year = (int) (timeBucket / 10000000000L);
        int month = (int) ((timeBucket / 100000000) % 100);
        int day = (int) ((timeBucket / 100000) % 100);
        int dayOfWeek = (int) ((timeBucket / 1000) % 100);
        int hour = (int) ((timeBucket / 100) % 100);
        int minute = (int) (timeBucket % 100);

        int newDay = day - (day % dayStep);
        if (newDay < dayOfWeek) {
            newDay += dayStep;
        }

        return year * 10000000000L + month * 100000000 + newDay * 100000 + dayOfWeek * 1000 + hour * 100 + minute;
    }

    public static void main(String[] args) {
        System.out.println(compressTimeBucket(20000105, 11)); // Output: 20000101
        System.out.println(compressTimeBucket(20000115, 11)); // Output: 20000112
        System.out.println(compressTimeBucket(20000123, 11)); // Output: 20000123
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            // Surrogate pair
            i++;
            size += 4;
        }
    }
    return size;
}

