import java.util.Properties;

public class PropertySubstitutor {

    /**
     * Find the value corresponding to <code>key</code> in <code>props</code>. Then perform variable substitution on the found value.
     */
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            throw new IllegalArgumentException("Key not found in properties: " + key);
        }
        return substituteVariables(value, props);
    }

    private static String substituteVariables(String value, Properties props) {
        int start = 0;
        while (true) {
            int startVar = value.indexOf("${", start);
            if (startVar == -1) {
                break;
            }
            int endVar = value.indexOf("}", startVar + 2);
            if (endVar == -1) {
                throw new IllegalArgumentException("Unmatched variable in properties: " + value);
            }
            String varName = value.substring(startVar + 2, endVar);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                throw new IllegalArgumentException("Variable not found in properties: " + varName);
            }
            value = value.substring(0, startVar) + varValue + value.substring(endVar + 1);
            start = startVar + varValue.length();
        }
        return value;
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("name", "John");
        props.setProperty("age", "30");
        props.setProperty("city", "${name}'s hometown");

        try {
            String result = findAndSubst("city", props);
            System.out.println(result);  // Output: John's hometown
        } catch (IllegalArgumentException e) {
            e.printStackTrace();
        }
    }
}

