public class StringUtility {

    /**
     * <p>Check if a String ends with a specified suffix (optionally case insensitive).</p>
     * @see String#endsWith(String)
     * @param str  the String to check, may be null
     * @param suffix the suffix to find, may be null
     * @param ignoreCase inidicates whether the compare should ignore case(case insensitive) or not.
     * @return <code>true</code> if the String starts with the prefix or both <code>null</code>
     */
    private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
        if (str == null || suffix == null) {
            return str == suffix;
        }
        if (ignoreCase) {
            return str.toLowerCase().endsWith(suffix.toLowerCase());
        } else {
            return str.endsWith(suffix);
        }
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(endsWith("Hello", "lo", true)); // true
        System.out.println(endsWith("Hello", "LO", false)); // false
        System.out.println(endsWith("Hello", "world", true)); // false
        System.out.println(endsWith(null, null, true)); // true
        System.out.println(endsWith("Hello", null, true)); // true
        System.out.println(endsWith(null, "Hello", true)); // true
    }
}

import java.net.URI;
import java.util.ArrayList;
import java.util.List;

public class URIUtils {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getPath();

        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // Remove the leading '/' if it exists
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        // Split the path by '/' to get individual path segments
        String[] segments = path.split("/");

        for (String segment : segments) {
            if (decode) {
                // Decode the segment if required
                segment = java.net.URLDecoder.decode(segment, "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    // Example implementation of PathSegmentImpl
    public static class PathSegmentImpl {
        private String segment;

        public PathSegmentImpl(String segment) {
            this.segment = segment;
        }

        public String getSegment() {
            return segment;
        }
    }
}

