public class DiagnosticContext {
    private static Stack<String> ndcStack = new Stack<>();

    public static void push(String context) {
        ndcStack.push(context);
    }

    public static String peek() {
        if (ndcStack.isEmpty()) {
            return "";
        }
        return ndcStack.peek();
    }

    public static void pop() {
        if (!ndcStack.isEmpty()) {
            ndcStack.pop();
        }
    }

    public static void main(String[] args) {
        push("Context 1");
        push("Context 2");
        System.out.println(peek()); // Output: Context 2
        pop();
        System.out.println(peek()); // Output: Context 1
        pop();
        System.out.println(peek()); // Output: (empty string)
    }
}

