import java.util.Stack;

public class FrameStack {
    private Stack<Object> stack = new Stack<>();

    public void push(Object obj) {
        stack.push(obj);
    }

    public Object pop() {
        return stack.pop();
    }

    public void pop(final String descriptor) {
        int numArgs = 0;
        if (descriptor.charAt(0) == '(') {
            int balance = 0;
            for (int i = 1; i < descriptor.length(); i++) {
                if (descriptor.charAt(i) == '(') {
                    balance++;
                } else if (descriptor.charAt(i) == ')') {
                    balance--;
                }
                if (balance == 0) {
                    numArgs = i - 1;
                    break;
                }
            }
        }

        for (int i = 0; i < numArgs; i++) {
            pop();
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.push(1);
        frameStack.push(2);
        frameStack.push(3);
        frameStack.push(4);
        frameStack.push(5);

        frameStack.pop("()"); // Pops 2 arguments

        System.out.println(frameStack.pop()); // Output: 3
        System.out.println(frameStack.pop()); // Output: 2
        System.out.println(frameStack.pop()); // Output: 1
    }
}

import java.io.IOException;

public class ByteArrayOutputStream {
    private byte[] buffer;
    private int size;

    public ByteArrayOutputStream() {
        this.buffer = new byte[1024];
        this.size = 0;
    }

    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("The byte array cannot be null");
        }
        if (off < 0 || len < 0 || off + len > b.length) {
            throw new IndexOutOfBoundsException("Invalid offset or length");
        }
        if (size + len > buffer.length) {
            expandBuffer(size + len);
        }
        System.arraycopy(b, off, buffer, size, len);
        size += len;
    }

    private void expandBuffer(int newCapacity) {
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }

    // Additional methods like toByteArray(), reset(), close() can be added here
}

public class ArrayUtils {
    /** 
     * Swaps the two elements at the specified indices in the given array.
     * @param <V> the type of elements in the array
     * @param arr the array
     * @param i the index of the first element
     * @param j the index of the second element
     */
    public static final <V> void swap(V[] arr, int i, int j) {
        if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
            throw new IndexOutOfBoundsException("Index out of bounds");
        }
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        Integer[] numbers = {1, 2, 3, 4, 5};
        System.out.println("Before swap: " + java.util.Arrays.toString(numbers));
        swap(numbers, 1, 3);
        System.out.println("After swap: " + java.util.Arrays.toString(numbers));
    }
}

