        System.out.println(comparator.compare(2.71, 3.14)); // Output: -1
        System.out.println(comparator.compare(3.14, 3.14)); // Output: 0
        System.out.println(comparator.compare(null, null)); // Output: 0
        System.out.println(comparator.compare(null, 3.14)); // Output: -1
