    protected Object convertToType(final Class<?> type, final Object value) throws Exception {
        if (type.equals(Character.class)) {
            if (value instanceof String) {
                if (value.toString().length() == 1) {
                    return value.toString().charAt(0);
                } else {
                    throw new Exception("Input string must be exactly one character long.");
                }
            } else {
                throw new Exception("Input value must be a String.");
            }
        } else {
            throw new Exception("Unsupported type for conversion.");
        }
    }

    public static void main(String[] args) {
        Converter converter = new Converter();
        try {
            System.out.println(converter.convertToType(Character.class, "a")); // Output: a
            System.out.println(converter.convertToType(Character.class, "ab")); // Throws Exception
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
}

import java.util.List;

public class StringChecker {

    /** 
     * Case in-sensitive Checks if the String contains any character in the given set of string. 
     */
    public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
        if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
            return false;
        }

        for (String searchStr : searchStrArray) {
            if (str.toLowerCase().contains(searchStr.toLowerCase())) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        List<String> searchStrArray = List.of("a", "b", "c");
        String str = "Hello, World!";
        System.out.println(containsAnyIgnoreCase(str, searchStrArray)); // Output: true
    }
}

