public final byte[] toByteArray() {
    // Assuming the buffer is a list of byte arrays
    List<byte[]> buffers = new ArrayList<>();
    // Add all buffers to the list
    for (byte[] buffer : buffers) {
        // Append each buffer to the result array
        result = Arrays.copyOf(result, result.length + buffer.length);
        System.arraycopy(buffer, 0, result, result.length - buffer.length, buffer.length);
    }
    // Convert the list of byte arrays to a single byte array
    return result;
}

