public class StringUnescape {

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        // Regular expression to match Java escape sequences
        Pattern pattern = Pattern.compile("\\\\(\\\\|n|r|t|b|f|u[0-9A-Fa-f]{4}|x[0-9A-Fa-f]{2})");
        Matcher matcher = pattern.matcher(str);

        // StringBuilder to build the unescaped string
        StringBuilder unescaped = new StringBuilder();

        int lastEnd = 0;
        while (matcher.find()) {
            // Append the part of the string before the match
            unescaped.append(str.substring(lastEnd, matcher.start()));

            // Handle different escape sequences
            String escapeSequence = matcher.group(1);
            switch (escapeSequence) {
                case "\\\\":
                    unescaped.append("\\");
                    break;
                case "\n":
                    unescaped.append("\n");
                    break;
                case "\r":
                    unescaped.append("\r");
                    break;
                case "\t":
                    unescaped.append("\t");
                    break;
                case "\b":
                    unescaped.append("\b");
                    break;
                case "\f":
                    unescaped.append("\f");
                    break;
                case "u[0-9A-Fa-f]{4}":
                    // Convert Unicode escape sequence to character
                    String unicode = escapeSequence.substring(2);
                    unescaped.append((char) Integer.parseInt(unicode, 16));
                    break;
                case "x[0-9A-Fa-f]{2}":
                    // Convert hexadecimal escape sequence to character
                    String hex = escapeSequence.substring(2);
                    unescaped.append((char) Integer.parseInt(hex, 16));
                    break;
                default:
                    throw new Exception("Unknown escape sequence: " + escapeSequence);
            }

            // Move the last end position to the end of the match
            lastEnd = matcher.end();
        }

        // Append the remaining part of the string after the last match
        unescaped.append(str.substring(lastEnd));

        return unescaped.toString();
    }

