import java.lang.reflect.Array;

public class ArrayUtils {

    /**
     * Returns a copy of the given array of size 1 greater than the argument. The last value of the array is left to the default value.
     * @param array The array to copy, must not be <code>null</code>.
     * @param newArrayComponentType If <code>array</code> is <code>null</code>, create asize 1 array of this type.
     * @return A new copy of the array of size 1 greater than the input.
     */
    private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
        if (array == null) {
            return Array.newInstance(newArrayComponentType, 1);
        }
        int length = Array.getLength(array);
        Class<?> componentType = array.getClass().getComponentType();
        Object newArray = Array.newInstance(componentType, length + 1);
        System.arraycopy(array, 0, newArray, 0, length);
        return newArray;
    }

    public static void main(String[] args) {
        // Example usage
        int[] originalArray = {1, 2, 3};
        int[] newArray = (int[]) copyArrayGrow1(originalArray, Integer.class);
        System.out.println("Original array: " + java.util.Arrays.toString(originalArray));
        System.out.println("New array: " + java.util.Arrays.toString(newArray));
    }
}

public class BinaryLogCalculator {

    /** 
     * Computes floor($\log_2 (n)$) $+ 1$
     */
    private int computeBinaryLog(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }
        return (int) Math.floor(Math.log(n) / Math.log(2)) + 1;
    }

    public static void main(String[] args) {
        BinaryLogCalculator calculator = new BinaryLogCalculator();
        int result = calculator.computeBinaryLog(16);
        System.out.println("The result is: " + result); // Output should be 4
    }
}

import java.util.HashSet;
import java.util.Set;

public class SetOperations {

    /**
     * Efficient way to compute the intersection between two sets
     * @param set1 set $1$
     * @param set2 set $2$
     * @return intersection of set $1$ and $2$
     */
    private Set<V> intersection(Set<V> set1, Set<V> set2) {
        Set<V> result = new HashSet<>(set1);
        result.retainAll(set2);
        return result;
    }

    public static void main(String[] args) {
        Set<Integer> set1 = new HashSet<>();
        set1.add(1);
        set1.add(2);
        set1.add(3);

        Set<Integer> set2 = new HashSet<>();
        set2.add(2);
        set2.add(3);
        set2.add(4);

        SetOperations operations = new SetOperations();
        Set<Integer> intersection = operations.intersection(set1, set2);

        System.out.println("Intersection: " + intersection); // Output: Intersection: [2, 3]
    }
}

