public class ArrayConverter {

    /**
     * Converts the given Collection into an array of Strings. The returned array does not contain <code>null</code> entries. Note that  {@link Arrays#sort(Object[])} will throw an {@link NullPointerException} if an array element is <code>null</code>.
     * @param collection The collection to convert
     * @return A new array of Strings.
     */
    static String[] toNoNullStringArray(Collection<?> collection) {
        if (collection == null) {
            return new String[0];
        }
        String[] array = new String[collection.size()];
        int index = 0;
        for (Object element : collection) {
            if (element != null) {
                array[index++] = element.toString();
            }
        }
        return array;
    }

    public static void main(String[] args) {
        // Example usage
        Collection<String> collection = Arrays.asList("apple", null, "banana", "cherry");
        String[] noNullArray = toNoNullStringArray(collection);
        System.out.println(Arrays.toString(noNullArray)); // Output: [apple, banana, cherry]
    }
}

