public class StringUtility {
    /**
     * Trim leading whitespace from the given String.
     * @param str the String to check
     * @return the trimmed String
     * @see java.lang.Character#isWhitespace
     */
    public static String trimLeadingWhitespace(String str) {
        if (str == null) {
            return null;
        }
        int start = 0;
        while (start < str.length() && Character.isWhitespace(str.charAt(start))) {
            start++;
        }
        return str.substring(start);
    }

    public static void main(String[] args) {
        System.out.println(trimLeadingWhitespace("  Hello, World!")); // Output: "Hello, World!"
        System.out.println(trimLeadingWhitespace("   ")); // Output: ""
        System.out.println(trimLeadingWhitespace(null)); // Output: null
    }
}

import java.io.IOException;

public class ClassFileReader {

    private final byte[] classFileBuffer;

    public ClassFileReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index");
        }

        int index = constantPoolEntryIndex * 2 + 1; // Start of the UTF-8 entry
        int length = classFileBuffer[index] & 0xFF; // Length of the UTF-8 string

        if (length > charBuffer.length) {
            throw new IllegalArgumentException("Buffer is too small to hold the UTF-8 string");
        }

        for (int i = 0; i < length; i++) {
            charBuffer[i] = (char) (classFileBuffer[index + i + 1] & 0xFF);
        }

        return new String(charBuffer, 0, length);
    }

    public static void main(String[] args) {
        // Example usage
        byte[] classFileBuffer = { // Example class file buffer
            // ... (class file bytes)
        };

        ClassFileReader reader = new ClassFileReader(classFileBuffer);
        char[] charBuffer = new char[256];
        try {
            String utfString = reader.readUtf(10, charBuffer); // Example index
            System.out.println(utfString);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

