public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        this();
        if (byteArrayValue != null) {
            putByteArray(byteArrayValue, byteOffset, byteLength);
        }
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            for (int i = 0; i < byteLength; i++) {
                data[size++] = 0;
            }
        } else {
            if (byteOffset + byteLength > byteArrayValue.length) {
                throw new IllegalArgumentException("byteOffset + byteLength exceeds the length of byteArrayValue");
            }
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
            size += byteLength;
        }
        return this;
    }

    public byte[] toByteArray() {
        byte[] result = new byte[size];
        System.arraycopy(data, 0, result, 0, size);
        return result;
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putByteArray(new byte[]{1, 2, 3, 4, 5}, 1, 3);
        System.out.println(new String(byteVector.toByteArray()));
    }
}

