public class StringManipulator {

    /** 
     * Delete any character in a given String.
     * @param inString the original String
     * @param charsToDelete a set of characters to delete. E.g. "az\n" will delete 'a's, 'z's and new lines.
     * @return the resulting String
     */
    public static String deleteAny(String inString, String charsToDelete) {
        Set<Character> deleteSet = new HashSet<>();
        for (char c : charsToDelete.toCharArray()) {
            deleteSet.add(c);
        }

        StringBuilder result = new StringBuilder();
        for (char c : inString.toCharArray()) {
            if (!deleteSet.contains(c)) {
                result.append(c);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        String original = "Hello, World!\n";
        String charsToDelete = "aeiou\n";
        String result = deleteAny(original, charsToDelete);
        System.out.println(result);  // Output: "Hll, Wrld!"
    }
}

