public class LogAppenderManager {
    private static final Logger logger = Logger.getLogger(LogAppenderManager.class);

    public int appendLoopOnAppenders(LoggingEvent event) {
        int count = 0;
        Appender[] appenders = logger.getAllAppenders();
        for (Appender appender : appenders) {
            try {
                appender.doAppend(event);
                count++;
            } catch (Exception e) {
                logger.error("Error appending event to appender: " + appender.getName(), e);
            }
        }
        return count;
    }
}

