import java.util.List;
import java.util.Set;

public class BucketManager {

    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        // Find the bucket with the minimum label
        Set<Integer> minLabelBucket = null;
        for (Set<Integer> bucket : bucketsByLabel) {
            if (bucket != null && !bucket.isEmpty()) {
                if (minLabelBucket == null || bucket.size() < minLabelBucket.size()) {
                    minLabelBucket = bucket;
                }
            }
        }

        // Check if we found a non-empty bucket
        if (minLabelBucket != null) {
            // Move all vertices from the minLabelBucket to bucket 0
            for (int vertex : minLabelBucket) {
                bucketsByLabel.get(0).add(vertex);
                labels.set(vertex, 0);
            }

            // Clear the minLabelBucket
            minLabelBucket.clear();
        }
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> bucketsByLabel = new ArrayList<>();
        bucketsByLabel.add(new HashSet<>(Arrays.asList(1, 2, 3)));
        bucketsByLabel.add(new HashSet<>(Arrays.asList(4, 5)));
        bucketsByLabel.add(new HashSet<>(Arrays.asList(6, 7, 8, 9)));

        List<Integer> labels = new ArrayList<>(Arrays.asList(1, 1, 1, 2, 2, 2, 3, 3, 3));
        int minLabel = 1;

        BucketManager manager = new BucketManager();
        manager.reload(bucketsByLabel, labels, minLabel);

        // Output the results
        System.out.println("Buckets by Label: " + bucketsByLabel);
        System.out.println("Labels: " + labels);
    }
}

