public class TokenParser {

    /**
     * Parses out a token until any of the given terminators is encountered.
     * @param terminators the array of terminating characters. Any of these characters when encountered signify the end of the token
     * @return the token
     */
    private String parseToken(final char[] terminators) {
        StringBuilder token = new StringBuilder();
        boolean foundTerminator = false;

        while (!foundTerminator) {
            int nextChar = System.in.read();
            if (nextChar == -1) {
                break; // End of input
            }
            char currentChar = (char) nextChar;
            if (isTerminator(currentChar, terminators)) {
                foundTerminator = true;
            } else {
                token.append(currentChar);
            }
        }

        return token.toString();
    }

    private boolean isTerminator(char currentChar, char[] terminators) {
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        TokenParser parser = new TokenParser();
        char[] terminators = {' ', '\n', '\t'};
        String token = parser.parseToken(terminators);
        System.out.println("Parsed token: " + token);
    }
}

public class StringManipulator {
    /**
     * Trim all occurrences of the supplied leading character from the given String.
     * @param str the String to check
     * @param leadingCharacter the leading character to be trimmed
     * @return the trimmed String
     */
    public static String trimLeadingCharacter(String str, char leadingCharacter) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        int index = 0;
        while (index < str.length() && str.charAt(index) == leadingCharacter) {
            index++;
        }
        return str.substring(index);
    }

    public static void main(String[] args) {
        System.out.println(trimLeadingCharacter("Hello, World!", 'H')); // Output: "ello, World!"
        System.out.println(trimLeadingCharacter("Hello, World!", 'W')); // Output: "Hello, World!"
        System.out.println(trimLeadingCharacter("Hello, World!", 'x')); // Output: "Hello, World!"
        System.out.println(trimLeadingCharacter("", 'x')); // Output: ""
        System.out.println(trimLeadingCharacter(null, 'x')); // Output: null
    }
}

