import java.util.ArrayList;
import java.util.List;
import org.javatuples.Pair;

public class SuffixSumCalculator {

    /** 
     * Computes a suffix sum of the  {@code bounds}. Returns computed suffix sum and the sum of all elements in the  {@code bounds list}.
     * @param bounds list of integers.
     * @return computed pair of suffix sum list and a sum of all elements.
     */
    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        if (bounds == null || bounds.isEmpty()) {
            return Pair.with(new ArrayList<>(), 0L);
        }

        List<Integer> suffixSumList = new ArrayList<>();
        long totalSum = 0;

        for (int i = bounds.size() - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            suffixSumList.add(totalSum);
        }

        // Reverse the suffix sum list to get the correct order
        List<Integer> reversedSuffixSumList = new ArrayList<>();
        for (int i = suffixSumList.size() - 1; i >= 0; i--) {
            reversedSuffixSumList.add(suffixSumList.get(i));
        }

        return Pair.with(reversedSuffixSumList, totalSum);
    }

    public static void main(String[] args) {
        SuffixSumCalculator calculator = new SuffixSumCalculator();
        List<Integer> bounds = List.of(1, 2, 3, 4, 5);
        Pair<List<Integer>, Long> result = calculator.computeSuffixSum(bounds);
        System.out.println("Suffix Sum List: " + result.getValue0());
        System.out.println("Total Sum: " + result.getValue1());
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range");
    }

    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

import java.util.List;

public class DoublyLinkedList<E> {
    private ListNode<E> head;
    private ListNode<E> tail;

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        if (list == null || list.isEmpty()) {
            return;
        }

        ListNode<E> current = list.head;
        while (current != null) {
            ListNode<E> next = current.next;
            list.removeListNode(current);
            addListNode(current);
            current = next;
        }
    }

    private void addListNode(ListNode<E> node) {
        if (head == null) {
            head = tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
    }

    private void removeListNode(ListNode<E> node) {
        if (node == head) {
            head = node.next;
        }
        if (node == tail) {
            tail = node.prev;
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        }
    }

    private static class ListNode<E> {
        E value;
        ListNode<E> prev;
        ListNode<E> next;

        ListNode(E value) {
            this.value = value;
        }
    }
}

