public class NameAbbreviator {
    /** 
     * Abbreviate name.
     * @param buf buffer to append abbreviation.
     * @param nameStart start of name to abbreviate.
     */
    public void abbreviate(final int nameStart, final StringBuffer buf) {
        if (nameStart < 0 || buf == null) {
            throw new IllegalArgumentException("Invalid input");
        }

        int nameEnd = nameStart + 3; // Assume abbreviate the next 3 characters
        if (nameEnd > buf.length()) {
            nameEnd = buf.length();
        }

        buf.append(buf.substring(nameStart, nameEnd));
    }

    public static void main(String[] args) {
        StringBuffer buf = new StringBuffer("JohnDoe");
        NameAbbreviator abbreviator = new NameAbbreviator();
        abbreviator.abbreviate(0, buf);
        System.out.println(buf.toString()); // Output: Joh
    }
}

