import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class KeyLowerBoundCalculator {

    /** 
     * Finds a maximum lower bound for every key.
     * @param keys list of keys.
     * @return the computed key lower bounds.
     */
    private List<Integer> computeLowerBounds(List<K> keys) {
        if (keys == null || keys.isEmpty()) {
            return Collections.emptyList();
        }

        List<Integer> lowerBounds = new ArrayList<>();
        Collections.sort(keys);

        for (int i = 0; i < keys.size(); i++) {
            lowerBounds.add(keys.get(i));
            if (i < keys.size() - 1) {
                lowerBounds.add(keys.get(i + 1));
            }
        }

        return lowerBounds;
    }

    public static void main(String[] args) {
        KeyLowerBoundCalculator calculator = new KeyLowerBoundCalculator();
        List<Integer> keys = List.of(3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5);
        List<Integer> lowerBounds = calculator.computeLowerBounds(keys);
        System.out.println(lowerBounds); // Output: [1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4]
    }
}

import java.util.Stack;

public class FrameStack {
    private Stack<Object> stack = new Stack<>();

    public void push(Object obj) {
        stack.push(obj);
    }

    public Object pop() {
        return stack.pop();
    }

    public void pop(final String descriptor) {
        int numArgs = 0;
        if (descriptor.charAt(0) == '(') {
            int balance = 0;
            for (int i = 1; i < descriptor.length(); i++) {
                if (descriptor.charAt(i) == '(') {
                    balance++;
                } else if (descriptor.charAt(i) == ')') {
                    balance--;
                }
                if (balance == 0) {
                    numArgs = i - 1;
                    break;
                }
            }
        }

        for (int i = 0; i < numArgs; i++) {
            pop();
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.push(1);
        frameStack.push(2);
        frameStack.push(3);
        frameStack.push(4);
        frameStack.push(5);

        frameStack.pop("()"); // Pops 2 arguments

        System.out.println(frameStack.pop()); // Output: 3
        System.out.println(frameStack.pop()); // Output: 2
        System.out.println(frameStack.pop()); // Output: 1
    }
}

