import java.util.Arrays;

public class ArrayUtils {

    /**
     * Returns a new array of Strings without null elements. Internal method used to normalize exclude lists (arrays and collections). Note that  {@link Arrays#sort(Object[])} will throw an {@link NullPointerException}if an array element is <code>null</code>.
     * @param array The array to check
     * @return The given array or a new array without null.
     */
    static String[] toNoNullStringArray(Object[] array) {
        if (array == null) {
            return new String[0];
        }

        int nonNullCount = 0;
        for (Object element : array) {
            if (element != null && element instanceof String) {
                nonNullCount++;
            }
        }

        String[] result = new String[nonNullCount];
        int index = 0;
        for (Object element : array) {
            if (element != null && element instanceof String) {
                result[index++] = (String) element;
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Object[] array = {"hello", null, "world", null, "java"};
        String[] noNullArray = toNoNullStringArray(array);
        System.out.println(Arrays.toString(noNullArray)); // Output: [hello, world, java]
    }
}

public class FilenameUtils {
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparatorIndex = indexOfLastSeparator(filename);
        if (lastSeparatorIndex == -1) {
            return -1;
        }
        int dotIndex = filename.lastIndexOf('.');
        if (dotIndex == -1 || dotIndex < lastSeparatorIndex) {
            return -1;
        }
        return dotIndex;
    }

    private static int indexOfLastSeparator(String filename) {
        int lastUnixSeparatorIndex = filename.lastIndexOf('/');
        int lastWindowsSeparatorIndex = filename.lastIndexOf('\\');
        return Math.max(lastUnixSeparatorIndex, lastWindowsSeparatorIndex);
    }

    public static void main(String[] args) {
        System.out.println(indexOfExtension("example.txt")); // Output: 4
        System.out.println(indexOfExtension("example"));    // Output: -1
        System.out.println(indexOfExtension("example/"));   // Output: -1
        System.out.println(indexOfExtension("example\\"));   // Output: -1
        System.out.println(indexOfExtension("example..txt")); // Output: -1
    }
}

public class CacheUtils {

    public static boolean isExpired(long timestamp, long expiredThreshold) {
        // Calculate the time difference between the current timestamp and the last update time
        long timeDifference = timestamp - expiredThreshold;

        // Check if the time difference is negative, which means the metrics should be removed from cache
        return timeDifference < 0;
    }

    public static void main(String[] args) {
        // Example usage
        long currentTime = System.currentTimeMillis();
        long lastUpdateTime = currentTime - 10000; // 10 seconds ago
        long expiredThreshold = 5000; // 5 seconds

        boolean shouldRemove = isExpired(lastUpdateTime, expiredThreshold);
        System.out.println("Should remove from cache: " + shouldRemove);
    }
}

import java.util.*;

public class Graph {
    private Map<Node, List<Edge>> adjacencyList;

    public Graph() {
        adjacencyList = new HashMap<>();
    }

    public void addNode(Node node) {
        adjacencyList.put(node, new ArrayList<>());
    }

    public void addEdge(Node from, Node to) {
        adjacencyList.get(from).add(new Edge(from, to));
    }

    public Edge edgeToNext(Node current) {
        List<Edge> edges = adjacencyList.get(current);
        if (edges == null || edges.isEmpty()) {
            return null; // No edges connected to the current node
        }
        return edges.get(0); // Return the first edge as the next edge
    }

    public static void main(String[] args) {
        Graph graph = new Graph();
        Node node1 = new Node("A");
        Node node2 = new Node("B");
        Node node3 = new Node("C");

        graph.addNode(node1);
        graph.addNode(node2);
        graph.addNode(node3);

        graph.addEdge(node1, node2);
        graph.addEdge(node2, node3);

        Edge edge = graph.edgeToNext(node1);
        if (edge != null) {
            System.out.println("Edge from " + edge.from + " to " + edge.to);
        } else {
            System.out.println("No edges connected to the current node.");
        }
    }

    static class Node {
        String name;

        Node(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    static class Edge {
        Node from;
        Node to;

        Edge(Node from, Node to) {
            this.from = from;
            this.to = to;
        }

        @Override
        public String toString() {
            return "Edge(" + from + " -> " + to + ")";
        }
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index >= str.length()) {
        return false;
    }
    int subLength = substring.length();
    if (subLength == 0) {
        return true;
    }
    for (int i = 0; i < subLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

import java.io.IOException;
import java.net.Socket;
import java.util.List;

public class LogAppender {
    private List<Socket> connectedClients;

    public LogAppender(List<Socket> connectedClients) {
        this.connectedClients = connectedClients;
    }

    protected void append(LoggingEvent event) {
        for (Socket client : connectedClients) {
            try {
                client.getOutputStream().write(event.getMessage().getBytes());
                client.getOutputStream().flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

